// Frontend/src/contexts/AuthContext.tsx - FIXED VERSION
import React, { createContext, useContext, useState, useEffect } from 'react';
import { User as FirebaseUser } from 'firebase/auth';
import { auth } from '../config/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

interface AuthContextType {
  currentUser: FirebaseUser | null;
  userId: string | null;
  userName: string | null;
  userEmail: string | null;
  userAvatar: string | null;
  loading: boolean;
  logout: () => Promise<void>;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<FirebaseUser | null>(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [userName, setUserName] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [userAvatar, setUserAvatar] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    console.log('🔐 AuthContext: Initializing...');
    
    // Listen to Firebase auth state
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      console.log('🔐 Auth state changed:', user ? 'User logged in' : 'No Firebase user');
      
      setCurrentUser(user);
      
      if (user) {
        // Firebase authenticated user
        console.log('✅ Firebase User:', {
          uid: user.uid,
          name: user.displayName,
          email: user.email,
        });
        
        setUserId(user.uid);
        setUserName(user.displayName);
        setUserEmail(user.email);
        setUserAvatar(user.photoURL);
        
        // Store in localStorage
        localStorage.setItem('userId', user.uid);
        localStorage.setItem('userName', user.displayName || 'User');
        localStorage.setItem('userEmail', user.email || '');
        localStorage.setItem('userAvatar', user.photoURL || '');
      } else {
        // No Firebase user - check localStorage
        const storedUserId = localStorage.getItem('userId');
        const storedUserName = localStorage.getItem('userName');
        const storedUserEmail = localStorage.getItem('userEmail');
        const storedUserAvatar = localStorage.getItem('userAvatar');
        
        if (storedUserId) {
          console.log('📦 Using localStorage user:', storedUserId);
          setUserId(storedUserId);
          setUserName(storedUserName);
          setUserEmail(storedUserEmail);
          setUserAvatar(storedUserAvatar);
        } else {
          console.log('❌ No user found');
          setUserId(null);
          setUserName(null);
          setUserEmail(null);
          setUserAvatar(null);
        }
      }
      
      setLoading(false);
    });

    return () => {
      console.log('🔐 AuthContext: Cleanup');
      unsubscribe();
    };
  }, []);

  const logout = async () => {
    try {
      console.log('🚪 Logging out...');
      
      // Sign out from Firebase
      await signOut(auth);
      
      // Clear localStorage
      localStorage.removeItem('userId');
      localStorage.removeItem('userName');
      localStorage.removeItem('userEmail');
      localStorage.removeItem('userAvatar');
      
      // Clear state
      setCurrentUser(null);
      setUserId(null);
      setUserName(null);
      setUserEmail(null);
      setUserAvatar(null);
      
      console.log('✅ Logged out successfully');
    } catch (error) {
      console.error('❌ Logout error:', error);
      throw error;
    }
  };

  const value: AuthContextType = {
    currentUser,
    userId,
    userName,
    userEmail,
    userAvatar,
    loading,
    logout,
    isAuthenticated: !!userId,
  };

  // Debug log
  useEffect(() => {
    console.log('🔍 Auth State:', {
      userId,
      userName,
      isAuthenticated: !!userId,
      loading,
    });
  }, [userId, userName, loading]);

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};
